// Compile Hel's generated JSON Schemas into one TypeScript declaration file.
//
// Called by tools/generate_artifacts.py, never by hand:
//   node tools/schema_to_ts.mjs <schemas dir> <output .d.ts>
// The frontends of every app import these types, so a contract change shows
// up as a TypeScript build error wherever it matters (Fenrir D11).
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { compile } from "json-schema-to-typescript";

const [schemasDir, outFile] = process.argv.slice(2);
const parts = [
  "/* Generated by tools/generate_artifacts.py from Hel's JSON Schemas. Do not edit. */",
];
for (const name of readdirSync(schemasDir).filter((f) => f.endsWith(".schema.json")).sort()) {
  const schema = JSON.parse(readFileSync(join(schemasDir, name), "utf8"));
  parts.push(
    await compile(schema, schema.title, {
      bannerComment: "",
      declareExternallyReferenced: true,
      format: true,
      style: { singleQuote: false, printWidth: 100 },
    }),
  );
}
writeFileSync(outFile, parts.join("\n").replace(/\r\n/g, "\n"));
